// Extract data from webhook
const inputData = $input.item.json.data;

// Validate input
if (!Array.isArray(inputData) || inputData.length === 0) {
  return [{
    json: {
      error: "Invalid input: expected array of records",
      scores: null
    }
  }];
}

// Define expected fields for validation
const expectedFields = ['id', 'name', 'email', 'amount'];
const totalRecords = inputData.length;
const totalFields = expectedFields.length * totalRecords;

// 1. COMPLETENESS SCORE (0-100)
let nullCount = 0;
inputData.forEach(record => {
  expectedFields.forEach(field => {
    if (record[field] === null || record[field] === undefined || record[field] === '') {
      nullCount++;
    }
  });
});
const completenessScore = Math.round(((totalFields - nullCount) / totalFields) * 100);

// 2. UNIQUENESS SCORE (0-100)
const idSet = new Set();
let duplicateCount = 0;
inputData.forEach(record => {
  if (idSet.has(record.id)) {
    duplicateCount++;
  } else {
    idSet.add(record.id);
  }
});
const uniquenessScore = Math.round(((totalRecords - duplicateCount) / totalRecords) * 100);

// 3. VALIDITY SCORE (0-100)
let invalidCount = 0;
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
inputData.forEach(record => {
  // Check email format
  if (record.email && !emailRegex.test(record.email)) {
    invalidCount++;
  }
  // Check amount is numeric
  if (record.amount && isNaN(Number(record.amount))) {
    invalidCount++;
  }
});
const validityScore = Math.round(((totalRecords * 2 - invalidCount) / (totalRecords * 2)) * 100);

// 4. OVERALL SCORE (weighted average)
const overallScore = Math.round(
  (completenessScore * 0.4) + 
  (uniquenessScore * 0.3) + 
  (validityScore * 0.3)
);

// Create metadata (NO RAW DATA)
const metadata = {
  recordCount: totalRecords,
  fieldsChecked: expectedFields,
  timestamp: new Date().toISOString(),
  datasetId: `DS_${Date.now()}`
};

// Output scores + metadata ONLY
return [{
  json: {
    metadata: metadata,
    scores: {
      completeness: completenessScore,
      uniqueness: uniquenessScore,
      validity: validityScore,
      overall: overallScore
    },
    dimensionDetails: {
      completeness: `${nullCount} null values out of ${totalFields} total fields`,
      uniqueness: `${duplicateCount} duplicate IDs detected`,
      validity: `${invalidCount} validation failures`
    }
  }
}];

const crypto = require('crypto');

// Get scores from previous node
const scoresData = $input.item.json;

// Encryption configuration (hackathon-level)
const algorithm = 'aes-256-cbc';
const secretKey = 'hackathon2026secretkey12345678';
const iv = crypto.randomBytes(16);

// Prepare data to encrypt
const dataToEncrypt = JSON.stringify({
  scores: scoresData.scores,
  metadata: scoresData.metadata,
  dimensionDetails: scoresData.dimensionDetails
});

// Encrypt
const cipher = crypto.createCipheriv(algorithm, Buffer.from(secretKey), iv);
let encrypted = cipher.update(dataToEncrypt, 'utf8', 'hex');
encrypted += cipher.final('hex');

// Create encrypted payload
const encryptedPayload = {
  encryptedData: encrypted,
  iv: iv.toString('hex'),
  algorithm: algorithm,
  encryptedAt: new Date().toISOString(),
  datasetId: scoresData.metadata.datasetId
};

// OUTPUT: Both encrypted (for storage) and plaintext (for GenAI)
return [{
  json: {
    encrypted: encryptedPayload,
    plainScores: scoresData.scores,
    metadata: scoresData.metadata,
    dimensionDetails: scoresData.dimensionDetails
  }
}];

const data = $('Encrypt Scores').item.json;

// Create GenAI prompt with ONLY scores and metadata
const prompt = `You are a data quality expert. Analyze these data quality scores and provide actionable recommendations.

DATASET METADATA:
- Dataset ID: ${data.metadata.datasetId}
- Total Records: ${data.metadata.recordCount}
- Fields Analyzed: ${data.metadata.fieldsChecked.join(', ')}
- Analysis Timestamp: ${data.metadata.timestamp}

DATA QUALITY SCORES:
- Completeness: ${data.plainScores.completeness}/100
  ${data.dimensionDetails.completeness}
- Uniqueness: ${data.plainScores.uniqueness}/100
  ${data.dimensionDetails.uniqueness}
- Validity: ${data.plainScores.validity}/100
  ${data.dimensionDetails.validity}
- Overall Quality: ${data.plainScores.overall}/100

IMPORTANT: You are receiving ONLY scores and metadata. No raw data is shared with you.

Please provide:
1. A brief summary of the data quality (2-3 sentences)
2. Top 3 specific recommendations to improve the lowest-scoring dimensions
3. Overall assessment of data readiness for production use

Format your response as clear, actionable guidance for a data team.`;

return [{
  json: {
    prompt: prompt,
    scores: data.plainScores,
    metadata: data.metadata,
    dimensionDetails: data.dimensionDetails
  }
}];

const groqResponse = $input.item.json;
const previousData = $('Prepare GenAI Prompt').item.json;

// Extract Groq AI text from response
// Groq uses OpenAI-compatible format: choices[0].message.content
let genAiText = 'Analysis unavailable';

if (groqResponse.choices && groqResponse.choices.length > 0) {
  genAiText = groqResponse.choices[0].message.content;
} else if (groqResponse.error) {
  genAiText = `Error from Groq API: ${groqResponse.error.message || 'Unknown error'}`;
}

// Create final user-facing output
const finalOutput = {
  success: true,
  datasetId: previousData.metadata.datasetId,
  timestamp: previousData.metadata.timestamp,
  qualityScores: {
    overall: previousData.scores.overall,
    dimensions: {
      completeness: previousData.scores.completeness,
      uniqueness: previousData.scores.uniqueness,
      validity: previousData.scores.validity
    }
  },
  scoreDetails: previousData.dimensionDetails,
  analysis: {
    summary: genAiText,
    generatedBy: "AI Analysis (Groq - Llama 3.1 70B)",
    note: "Analysis based on scores only - no raw data shared"
  },
  datasetInfo: {
    recordCount: previousData.metadata.recordCount,
    fieldsAnalyzed: previousData.metadata.fieldsChecked
  },
  privacyNotice: "Raw data was processed locally and encrypted. Only quality scores were shared with AI for analysis."
};

return [{
  json: finalOutput
}];
